/**
 * Macro that requests a skill check from multiple, selectable players at once.
 * Same underlying request mechanism as "Skill Request", but lets the GM pick which
 * connected players to ask via checkboxes (defaulting to whichever players' tokens
 * are currently selected on the canvas), and optionally keep the request whispered
 * to just those players (plus GMs) rather than posting it to the whole table.
 */
const SKILLS = CONFIG.MGT2.getDefaultSkills();
const fields = foundry.applications.fields;

let skillOptions = [];
let skillLabels = {};
for (let id in SKILLS) {
  let skill = SKILLS[id];
  skillLabels[id] = game.i18n.localize("MGT2.Skills." + id);
  skillOptions.push({
    label: game.i18n.localize("MGT2.Skills." + id),
    value: id
  });
  if (skill.specialities) {
    for (let spec in skill.specialities) {
      skillLabels[id+"."+spec] = `${game.i18n.localize("MGT2.Skills." + id)} (${game.i18n.localize("MGT2.Skills." + spec)})`;
      skillOptions.push({
        label: `${game.i18n.localize("MGT2.Skills." + id)} (${game.i18n.localize("MGT2.Skills." + spec)})`,
        value: id + "." + spec
      });
    }
  }
}

// Which traveller actor "belongs to" a given user - mirrors MgT2Actor.findActorOwner()'s own
// priority order (the system.player field first, since that's this system's primary ownership
// convention), just resolved in the opposite direction (user -> their character).
function resolvePlayerCharacter(user) {
  let actor = game.actors.find(a => a.type === "traveller" && a.system.player === user.name);
  if (!actor && user.character) {
    actor = user.character;
  }
  if (!actor) {
    actor = game.actors.find(a => a.type === "traveller" && a.testUserPermission(user, "OWNER"));
  }
  return actor;
}

const players = game.users.filter(u => u.active && !u.isGM)
  .map(u => ({ user: u, actor: resolvePlayerCharacter(u) }))
  .filter(p => p.actor);

if (players.length === 0) {
  ui.notifications.warn("No connected players with an owned character to request a roll from.");
} else {

// A player can own more than one actor (e.g. a PC plus a crew-role actor), so checking against
// only each player's single "representative" character would miss a selected token that
// happens to be their other actor - check every selected token's actor against each candidate
// player's own ownership criteria instead.
const controlledActors = (canvas.tokens?.controlled ?? []).map(t => t.actor).filter(Boolean);
function playerHasControlledToken(user) {
  return controlledActors.some(a => a.system.player === user.name || a.testUserPermission(user, "OWNER"));
}

const skillInput = fields.createSelectInput({
  name: "skill",
  options: skillOptions
});
const difficultyInput = fields.createNumberInput({
  name: 'difficulty',
  value: 8
});
const characteristicInput = fields.createSelectInput({
  name: "characteristic",
  options: [
    { label: "STR", value: "STR" },
    { label: "DEX", value: "DEX" },
    { label: "END", value: "END" },
    { label: "INT", value: "INT" },
    { label: "EDU", value: "EDU" },
    { label: "SOC", value: "SOC" },
  ],
  value: "INT"
});
const rollModeOptions = Object.entries(CONFIG.Dice.rollModes).map(([value, mode]) => ({
  label: game.i18n.localize(mode.label),
  value
}));
const rollModeInput = fields.createSelectInput({
  name: "rollMode",
  options: rollModeOptions,
  value: game.settings.get("core", "rollMode")
});
const privateInput = fields.createCheckboxInput({
  name: "isPrivate",
  value: false
});
const titleInput = fields.createTextInput({
  name: 'description',
  value: "Make a skill roll"
});
const successInput = fields.createTextInput({
  name: 'success',
  value: "Success"
});
const failInput = fields.createTextInput({
  name: 'failure',
  value: "Failure"
});

const playerCheckboxes = players.map(p => {
  const checked = playerHasControlledToken(p.user);
  const cb = fields.createCheckboxInput({ name: `player_${p.user.id}`, value: checked });
  return `<div><label>${cb.outerHTML} ${p.actor.name} (${p.user.name})</label></div>`;
}).join("");

const content = `
<div class="grid grid-4col">
<div><label>Select skill</label>${skillInput.outerHTML}</div>
<div><label>Difficulty</label>${difficultyInput.outerHTML}</div>
<div><label>Characteristic</label>${characteristicInput.outerHTML}</div>
<div><label>Visibility</label>${rollModeInput.outerHTML}</div>
</div>
<div><label>Roll Text</label>${titleInput.outerHTML}</div>
<div><label>Success Text</label>${successInput.outerHTML}</div>
<div><label>Failure Text</label>${failInput.outerHTML}</div>
<fieldset>
<legend>Request from</legend>
${playerCheckboxes}
</fieldset>
<div><label>${privateInput.outerHTML} Make Request Private</label></div>
`;

const data = await foundry.applications.api.DialogV2.input({
  window: { title: "Request skill check (multiple players)" },
  content: content,
  ok: {
    label: "Send Request"
  }
});

if (data) {
  const selectedPlayers = players.filter(p => data[`player_${p.user.id}`]);
  if (selectedPlayers.length === 0) {
    ui.notifications.warn("No players were selected - request not sent.");
  } else {
    let jsonData = {
        skill: data.skill,
        "dm": 0,
        "rollType": "standard",
        "difficulty": data.difficulty,
        "cha": data.characteristic,
        "description": data.description,
        "success": data.success,
        "failure": data.failure,
        "rollMode": data.rollMode
    };

    let icon = data.skill.replaceAll(/\..*/g, "");
    let contentData = {
      skillIcon: `systems/mgt2e-piggy/icons/skills/${icon}.svg`,
      skillTitle: skillLabels[data.skill],
      skillFqn: data.skill,
      json: JSON.stringify(jsonData),
      difficulty: data.difficulty,
      description: data.description,
      requestedOf: selectedPlayers.map(p => p.actor.name).join(", ")
    };

    const c = await foundry.applications.handlebars.renderTemplate("systems/mgt2e-piggy/templates/chat/skill-request.html", contentData);
    let whisper = undefined;
    if (data.isPrivate) {
      const gmIds = game.users.filter(u => u.isGM).map(u => u.id);
      whisper = Array.from(new Set([...selectedPlayers.map(p => p.user.id), ...gmIds]));
    }
    let chatData = {
        content: c,
        whisper: whisper,
        rollMode: game.settings.get("core", "rollMode")
    }
    ChatMessage.create(chatData, {});
  }
}

}
